        }
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + name + " role=" + role.key());
        return held;
    }

    /** Whether a user may settle a claim showing a due (null: n/a, within any limit): a steward
     *  settles anything, a clerk only a due at or below the sheet's clerk limit, if it has one. */
    @Transactional(readOnly = true)
    public boolean maySettle(String sheetId, String user, BigDecimal due) {
        if (due == null || roleOf(sheetId, user) == Role.STEWARD) {
            return true;
        }
        BigDecimal limit = clerkLimit(sheetId);
        return limit == null || due.compareTo(limit) <= 0;
    }

    /** The roles the sheet's permission matrix sets for each action, as set; an action left blank
     *  (keeping its standing rule) is left out. */
    @Transactional(readOnly = true)
    public Map<Permission, String> permissions(String sheetId) {
        Map<Permission, String> out = new EnumMap<>(Permission.class);
        permissions.findBySheetId(sheetId).forEach(p -> out.put(p.getAction(), p.getRoles()));
        return out;
    }

    /** Set the roles that may take an action (blank: its standing rule), comma separated, the
     *  sheet created first if it was never loaded; not dated, it applies from now on. */
    @Transactional
    public String setPermission(String sheetId, String user, Permission action, String rolesText) {
        sheets.load(sheetId, user);
        sheets.lock(sheetId);
        SheetPermission held = permissions.findBySheetIdAndAction(sheetId, action.key()).orElse(null);
        if (rolesText.isEmpty()) {
            if (held != null) {
                permissions.delete(held);
            }
    private BigDecimal amountOn(String key, LocalDate on, BigDecimal starting) {
        return settingOn(key, on)
                .map(d -> d.getValue() == null ? starting : new BigDecimal(d.getValue()))
                .orElse(starting);
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    public BigDecimal getClerkLimit() {
        return amountOn(CLERK_LIMIT, today, null);
    }

    /** The floor in force on the sheet's today. */
    public BigDecimal getFloor() {
        return floorOn(today);
    }

    }

    /** The proof threshold in force on a date: a claim dated then whose due is above it cannot be
     *  settled or approved without a proof; null when there is none. */
    public BigDecimal proofThresholdOn(LocalDate on) {
        return amountOn(PROOF_THRESHOLD, on, null);
    }

    /** The proof threshold in force on a date for a grade: its own then when one is set, else the
     *  sheet's then; null when there is none. */
    public BigDecimal proofThresholdFor(String grade, LocalDate on) {
        BigDecimal own = grade == null ? null : amountOn(PROOF_THRESHOLD_OF_GRADE + grade, on, null);
        return own != null ? own : proofThresholdOn(on);
    }

    /** The note threshold in force on the sheet's today; null when there is none. */
    public BigDecimal getNoteThreshold() {
        return noteThresholdOn(today);
    }

    /** The note threshold in force on a date: a claim dated then whose due is above it cannot be
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return asOf == null ? view(sheetId) : viewAsOf(history.asOf(sheetId, asOf));
    }

    @PutMapping("/settings/clerk-limit")
    public SettingsView setClerkLimit(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ClerkLimitForm body) {
        BigDecimal limit = body.value().isEmpty() ? null : new BigDecimal(body.value());
        service.setClerkLimit(sheetId, user.trim(), limit, fromOf(body.from()));
        return view(sheetId);
    }

    @PutMapping("/settings/floor")
    public SettingsView setFloor(
            @Valid @RequestBody ProofThresholdForm body) {
        BigDecimal threshold = body.value().isEmpty() ? null : new BigDecimal(body.value());
        service.setProofThreshold(sheetId, user.trim(), threshold, fromOf(body.from()));
        return view(sheetId);
    }

    @PutMapping("/settings/proof-threshold/{grade}")
    public SettingsView setGradeProofThreshold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable @NotNull @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody ProofThresholdForm body) {
        BigDecimal threshold = body.value().isEmpty() ? null : new BigDecimal(body.value());
        service.setGradeProofThreshold(sheetId, user.trim(), grade, threshold, fromOf(body.from()));
        return view(sheetId);
    }

    @PutMapping("/settings/note-threshold")
    public SettingsView setNoteThreshold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
